{
  "definition_simple": "指跳出作品或事物本身，从更高层次对其结构、规则或虚构本质进行自我反思与审视的（即“元-”）。",
  "definition_standard": "对应西方文艺理论中的前缀“meta-”，指超越并审视现有系统、认知框架或叙事规则的属性；多用于文学艺术批评，特指具有自反性、自我解构或刻意暴露虚构机制的特征。",
  "pos": "区别词",
  "semantic_class": "property",
  "sentences": [
    {
      "text": "这部后设电影打破了第四面墙，直接与观众对话。",
      "tier": "T2"
    },
    {
      "text": "读者在这本后设小说中常能看到作者谈论自己的写作过程。",
      "tier": "T3"
    },
    {
      "text": "舞台剧通过后设的手法让观众随时意识到这只是一场戏。",
      "tier": "T3"
    },
    {
      "text": "该剧采用了后设的叙事结构，在戏中戏里层层嵌套。",
      "tier": "T4"
    },
    {
      "text": "导演运用后设视听语言，深刻揭示了影视工业本身的虚幻感。",
      "tier": "T4"
    },
    {
      "text": "后设叙述打破了传统现实主义文学所构建的“逼真幻象”。",
      "tier": "T5"
    },
    {
      "text": "这篇学术书评着重探讨了卡尔维诺作品中的后设维度与自反性特征。",
      "tier": "T5"
    },
    {
      "text": "文艺理论界常将后现代主义思潮与后设技巧的大规模流行联系起来。",
      "tier": "T5"
    },
    {
      "text": "这种后设反思动摇了主客二元对立，将认知框架本身置于审视之下。",
      "tier": "T6"
    },
    {
      "text": "文本内部的自指符号产生了一种后设张力，彻底解构了单一确定的真理话语。",
      "tier": "T6"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "后撤",
      "explanation": "声母不同（sh 与 ch），“后撤”意为向后撤退，与文艺理论概念“后设”含义完全无关。"
    },
    {
      "word": "厚实",
      "explanation": "声调与韵母相近但第二字为轻声且韵母不同（shè 与 shi），“厚实”指厚度大或物资丰富，与“后设”毫无关联。"
    },
    {
      "word": "候审",
      "explanation": "第二字韵母与声调不同（shè 与 shěn），“候审”为法律用语指等待审讯，与“后设”音近义异。"
    }
  ],
  "primary_collocate": "小说",
  "collocation_distractors": [
    {
      "word": "故事",
      "explanation": "“后设”通常与形式和文类术语搭配（如“后设小说”“后设叙述”），一般不直接与日常词汇“故事”组合成固定搭配。"
    },
    {
      "word": "构思",
      "explanation": "“后设”指涉自反结构而非创作构思的动作或过程，“后设构思”在现代汉语批评话语中并非惯用搭配。"
    },
    {
      "word": "思想",
      "explanation": "“后设思想”语义含混，中文讨论认知反思时通常使用“元认知”或“批判性反思”，不使用“后设思想”。"
    }
  ],
  "collocation_wrong_collocate": "假想",
  "cloze_distractors": [
    {
      "word": "预设",
      "explanation": "“预设”表示事先的假定或前提，不能用来修饰打破虚构界限、进行自我反思的叙事手法。"
    },
    {
      "word": "附设",
      "explanation": "“附设”是动词，指附带设立机构或设施，词性与修饰艺术特征的语境不符。"
    },
    {
      "word": "陈设",
      "explanation": "“陈设”意为摆设或布置，为普通名词或动词，在此完全无法修饰“电影”的叙事形式。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "公司在会议中后设了一个新的副总裁职位来应对业务扩张。",
      "explanation": "误将“后设”当成了动词“事后设立/增设”使用，混淆了学术前缀“meta-”与字面汉字“后+设”的含义。"
    },
    {
      "sentence": "这道几何题隐藏了一个必须先证明的后设条件。",
      "explanation": "误将“后设”与“预设/前提条件”混为一谈，数学或逻辑学中应使用“预设”或“已知条件”。"
    },
    {
      "sentence": "小王性格特别后设，大家跟他相处都觉得很舒服。",
      "explanation": "误将专有文学理论属性词泛化为修饰人际性格特征的形容词，属于严重的范畴错位。"
    }
  ],
  "spot_incorrect": {
    "sentence": "为了弥补前期规划的不足，管委会决定在二期工程中后设三个安全巡查岗位。",
    "error_description": "“后设”是专有名词/区别词（指meta-的自反属性），不能作为动词充当“事后增设”使用。",
    "corrected": "为了弥补前期规划的不足，管委会决定在二期工程中追加设立三个安全巡查岗位。"
  },
  "word_family_forms": [
    "后设小说",
    "后设戏剧",
    "后设叙述",
    "后设认知"
  ],
  "word_family_fake_forms": [
    "后设家",
    "被后设",
    "后设化度"
  ],
